  // The GPU path also works in workers/headless tests with ordinary typed texture data.
  if (typeof document === "undefined")
    return {
      source: () => ({
        width: 2,
        height: 2,
        buffer: new Uint8Array([
          255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 255, 255, 255, 255,
        ]),
      }),
      label: () => "Typed image input",
      setActive() {},
      dispose() {},
    };
  const video = document.createElement("video");
  video.crossOrigin = "anonymous";
  video.muted = true;
  video.loop = true;
  video.playsInline = true;
  video.preload = "auto";
  video.controls = true;
  video.setAttribute("aria-label", "Source video");
  const fallback = document.createElement("canvas");
  fallback.width = 256;
  fallback.height = 144;
  const context = fallback.getContext("2d");
  let active = true,
    bitmap,
    objectURL,
    disposed = false,
    videoLabel = "Sample video \xB7 MDN CC0 flower",
    label = "Loading sample video\u2026";
  const play = () => {
    if (active && !bitmap && !disposed)
      video.play().catch((error) => {
        if (error.name === "NotAllowedError")
          label = "Press Play video to start playback";
      });
  };
  video.addEventListener("loadeddata", () => {
    label = videoLabel;
    play();
  });
  video.addEventListener("error", () => {
    label =
      "Video unavailable \xB7 generated fallback. Choose a local video or image.";
  });
  function loadVideo(url, title = "Sample video \xB7 MDN CC0 flower") {
    videoLabel = title;
    label = "Loading " + title + "\u2026";
    bitmap?.close();
    bitmap = undefined;
    video.pause();
    video.src = url;
    video.load();
    play();
  }
  loadVideo(sampleVideo);
  return {
    source(time) {
      if (bitmap) return bitmap;
      if (video.readyState >= 2) return video;
      const gradient = context.createLinearGradient(0, 0, 256, 144);
      gradient.addColorStop(0, "#094851");
      gradient.addColorStop(1, "#f8b46c");
      context.fillStyle = gradient;
      context.fillRect(0, 0, 256, 144);
      context.fillStyle = "#e7fff1";
      context.beginPath();
      context.arc(128 + Math.sin(time / 900) * 75, 72, 34, 0, Math.PI * 2);
      context.fill();
      return fallback;
    },
    label: () => label,
    setActive(value) {
      active = value;
      if (active) play();
      else video.pause();
    },
    mountControls(container, invalidate) {
      const input = document.createElement("input");
      input.type = "file";
      input.accept = "video/*,image/*";
      const caption = document.createElement("label");
      caption.textContent = "Video or image file ";
      caption.append(input);
      input.addEventListener("change", async () => {
        const file = input.files[0];
        if (!file) return;
        try {
          if (objectURL) URL.revokeObjectURL(objectURL);
          if (file.type.startsWith("image/")) {
            video.pause();
            bitmap?.close();
            bitmap = await createImageBitmap(file);
            label = file.name;
          } else {
            objectURL = URL.createObjectURL(file);
            loadVideo(objectURL, file.name);
          }
          invalidate();
        } catch (error) {
          label = error.message;
          invalidate();
        }
      });
      const playButton = document.createElement("button");
      playButton.textContent = "Play video";
      playButton.addEventListener("click", () => {
        active = true;
        play();
        invalidate();
      });
      const reset = document.createElement("button");
      reset.textContent = "Use sample video";
      reset.addEventListener("click", () => {
        if (objectURL) URL.revokeObjectURL(objectURL);
        objectURL = undefined;
        input.value = "";
        loadVideo(sampleVideo);
        invalidate();
      });
      const source = document.createElement("details");
      const summary = document.createElement("summary");
      summary.textContent = "Source video";
      source.append(summary, video);
      const group = document.createElement("div");
      group.className = "media-input-controls";
      group.append(caption, playButton, reset, source);
      container.append(group);
    },
    dispose() {
      disposed = true;
      video.pause();
      video.removeAttribute("src");
      video.load();
      bitmap?.close();
      if (objectURL) URL.revokeObjectURL(objectURL);
    },
  };
